dashboard.definition:
{
    "title": "Secure Infrastructure Status",
    "description": "Track current infrastructure state, exceptions, and emerging operational risk.",
    "inputs": {
        "input_time_range": {
            "options": {
                "defaultValue": "-24h@h,now",
                "token": "time_tok"
            },
            "title": "Time Range",
            "type": "input.timerange"
        }
    },
    "defaults": {
        "visualizations": {
            "global": {
                "showLastUpdated": true,
                "showProgressBar": true
            }
        }
    },
    "visualizations": {
        "viz_header_bg": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#1e293b",
                "strokeColor": "rgba(14,165,233,0.42)",
                "rx": 10
            }
        },
        "viz_header_icon": {
            "type": "splunk.image",
            "title": "Secure Infrastructure Status",
            "options": {
                "preserveAspectRatio": true,
                "src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/secure-infrastructure.svg"
            }
        },
        "viz_header": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#f1f5f9",
                "markdown": "# Secure Infrastructure Status\nTrack current infrastructure state, exceptions, and emerging operational risk\\."
            }
        },
        "viz_card_01_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#0f172a",
                "strokeColor": "rgba(14,165,233,0.42)",
                "rx": 12
            }
        },
        "viz_card_01_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#f1f5f9",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Access Point Estate**"
            }
        },
        "viz_card_01_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#7dd3fc",
                "fontSize": "custom",
                "customFontSize": 11,
                "markdown": "Asset  •  Secure Infrastructure"
            }
        },
        "viz_card_01_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#cbd5e1",
                "fontSize": "custom",
                "customFontSize": 12,
                "markdown": "Total count of unique Cisco Meraki access points in the managed wireless infrastructure, providing the wireless footprint KPI\\."
            }
        },
        "viz_card_01_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#f1f5f9",
                "majorFontSize": 38,
                "majorValue": "> primary | seriesByName(\"ap_count\") | lastPoint()",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            }
        },
        "viz_card_01_trend": {
            "type": "splunk.area",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "off",
                "seriesColors": [
                    "#7dd3fc",
                    "#6ee7b7",
                    "#fdba74",
                    "#fda4af"
                ],
                "dataValuesDisplay": "minmax",
                "lineWidth": 3,
                "markerDisplay": "outlined",
                "nullValueDisplay": "connect",
                "showYMajorGridLines": true,
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "x": "> primary | seriesByName(\"_time\")",
                "y": "> primary | seriesByName(\"ap_count\")"
            }
        },
        "viz_card_01_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=Access%20Point%20Estate&target=Secure%20Networking%20-%20Site%20Inventory%20Rollup"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_02_background": {
            "type": "splunk.rectangle",
            "options": {
